begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir helpers/fms_visit_assignment_fixture.psql
reset role;
update user_profiles set buddy_id=(select id from visit_assignment_fixture where name='e') where id=(select id from visit_assignment_fixture where name='d');
insert into user_availability(tenant_id,user_profile_id,date,status) values((select id from visit_assignment_fixture where name='tenant'),(select id from visit_assignment_fixture where name='d'),(now() at time zone 'Asia/Kolkata')::date,'absent');
select set_config('request.jwt.claim.sub',(select id::text from visit_assignment_fixture where name='b_auth'),true);
set local role authenticated;
create temporary table coverage_preview(request jsonb,handoffs jsonb,base jsonb,preview jsonb);
grant all on coverage_preview to authenticated;
insert into coverage_preview(request,handoffs) values(jsonb_build_object('kind','stage_form','instanceStageId',(select id from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='call')),'formTemplateId',(select id from visit_assignment_fixture where name='form'),'answers',jsonb_build_object('next_employee',(select id from visit_assignment_fixture where name='c')),'outcome','','remark','','checklist','{}'::jsonb),jsonb_build_array(jsonb_build_object('targetStageId',(select id from visit_assignment_fixture where name='demo'),'userProfileId',(select id from visit_assignment_fixture where name='d'))));
update coverage_preview set base=preview_fms_work_transition(request),preview=preview_fms_work_transition(request,handoffs);
select is((select preview#>>'{destinations,0,selectedUserId}' from coverage_preview),(select id::text from visit_assignment_fixture where name='d'),'selected employee is preserved before coverage');
select is((select preview#>>'{destinations,0,effectiveUserId}' from coverage_preview),(select id::text from visit_assignment_fixture where name='e'),'coverage employee is shown before confirmation');
select is((select preview#>>'{destinations,0,selectedEmployeeName}' from coverage_preview),'Employee D','raw selected employee has a human name');
select is((select preview#>>'{destinations,0,employeeName}' from coverage_preview),'Employee E','effective employee has a human name');
select throws_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),handoffs,base->>'fingerprint') from coverage_preview$$,'23514','Workflow handoff changed. Review the current preview and confirm again.','base preview cannot confirm an unreviewed covered handoff');
reset role;
update user_profiles set buddy_id=(select id from visit_assignment_fixture where name='c') where id=(select id from visit_assignment_fixture where name='d');
set local role authenticated;
select throws_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),handoffs,preview->>'fingerprint') from coverage_preview$$,'23514','Workflow handoff changed. Review the current preview and confirm again.','coverage change after preview requires fresh confirmation');
reset role;
update user_profiles set buddy_id=(select id from visit_assignment_fixture where name='e') where id=(select id from visit_assignment_fixture where name='d');
set local role authenticated;
select lives_ok($$select transition_fms_work_with_audit(request,gen_random_uuid(),handoffs,preview->>'fingerprint') from coverage_preview$$,'confirmed coverage activates atomically');
reset role;
select is((select selected_user_ids from fms_stage_assignment_decisions decision join fms_instance_stages work on work.id=decision.target_instance_stage_id where work.fms_instance_id=(select id from visit_assignment_fixture where name='instance') and work.fms_stage_id=(select id from visit_assignment_fixture where name='demo')),array[(select id from visit_assignment_fixture where name='d')],'provenance keeps the original selected employee');
select is((select assigned_to from fms_instance_stages where fms_instance_id=(select id from visit_assignment_fixture where name='instance') and fms_stage_id=(select id from visit_assignment_fixture where name='demo')),array[(select id from visit_assignment_fixture where name='e')],'actual work belongs to the confirmed coverage employee');
select * from finish();
rollback;
